const width = 620;
const height = 520;

const svg = d3.select('#chart')
  .append('svg')
  .attr('width', width)
  .attr('height', height);

const tooltip = d3.select('body').append('div')
  .attr('class', 'tooltip')
  .style('opacity', 0);

function formatCap(val) {
  if (!val || isNaN(val)) return 'N/A';
  const abs = Math.abs(val);
  if (abs >= 1e12) return (val / 1e12).toFixed(2) + 'T';
  if (abs >= 1e9) return (val / 1e9).toFixed(2) + 'B';
  if (abs >= 1e6) return (val / 1e6).toFixed(2) + 'M';
  return val.toFixed(0);
}

d3.csv('data/stock-descriptions.csv').then(data => {
  data.forEach(d => {
    d.marketCap = d.marketCap === '' ? null : +d.marketCap;
  });

  const sectors = Array.from(new Set(data.map(d => d.sector)));
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10);

  const caps = data.filter(d => d.marketCap).map(d => d.marketCap);
  const sizeScale = d3.scaleSqrt()
    .domain([d3.min(caps), d3.max(caps)])
    .range([12, 40]);

  data.forEach(d => {
    d.radius = d.marketCap ? sizeScale(d.marketCap) : 15;
  });

  const center = { x: width / 2, y: height / 2 };
  const clusterRadius = Math.min(width, height) / 3;
  const sectorCenters = {};
  sectors.forEach((s, i) => {
    const angle = (i / sectors.length) * 2 * Math.PI;
    sectorCenters[s] = {
      x: center.x + clusterRadius * Math.cos(angle),
      y: center.y + clusterRadius * Math.sin(angle)
    };
  });

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.12))
    .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.12))
    .force('collide', d3.forceCollide(d => d.radius + 1))
    .force('charge', d3.forceManyBody().strength(0.5))
    .on('tick', ticked);

  const node = svg.append('g')
    .selectAll('g')
    .data(data)
    .enter().append('g')
    .attr('class', 'node');

  node.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector))
    .attr('stroke', '#333')
    .attr('stroke-width', 0.5);

  node.append('text')
    .text(d => d.ticker)
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .style('font-size', d => Math.min(12, d.radius))
    .style('fill', '#fff')
    .style('pointer-events', 'none');

  node.on('mouseover', (event, d) => {
      if (!d.marketCap) return;
      tooltip
        .style('opacity', 1)
        .html(`<strong>${d.ticker}</strong><br>${d['full name']}<br>${d.sector}`);
    })
    .on('mousemove', (event) => {
      tooltip
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 28) + 'px');
    })
    .on('mouseout', () => {
      tooltip.style('opacity', 0);
    })
    .on('click', (event, d) => selectTicker(d.ticker));

  function ticked() {
    node.attr('transform', d => `translate(${d.x},${d.y})`);
  }

  // Legend
  const legend = svg.append('g')
    .attr('class', 'legend')
    .attr('transform', 'translate(10,10)');

  sectors.forEach((s, i) => {
    const g = legend.append('g')
      .attr('transform', `translate(0,${i * 20})`);
    g.append('circle')
      .attr('cx', 6)
      .attr('cy', 6)
      .attr('r', 6)
      .attr('fill', color(s));
    g.append('text')
      .attr('x', 16)
      .attr('y', 10)
      .text(s);
  });

  // Table
  const tbody = d3.select('#stock-table tbody');

  const rows = tbody.selectAll('tr')
    .data(data)
    .enter().append('tr')
    .on('click', (event, d) => selectTicker(d.ticker));

  rows.append('td').text(d => d.ticker);
  rows.append('td').text(d => d['full name']);
  rows.append('td').text(d => d.sector);
  rows.append('td').text(d => formatCap(d.marketCap));

  function selectTicker(ticker) {
    d3.selectAll('.node').classed('selected', d => d.ticker === ticker);
    d3.selectAll('#stock-table tbody tr').classed('selected', d => d.ticker === ticker);
  }
});
